window.MG_LAZY_DATA["data/lazy/owner-courses/c001-cbd1fb1deb17bddd.json"]={sha256:"cbd1fb1deb17bddd04c4adaf935c75f4658de36845817b847704c96ed1aa764e",value:{"id":"c001","title":"Airbus A350 複材客機系統工程","titleEn":"Airbus A350 composite airliner systems","category":"aerospace","summary":"從機翼載荷、複材方向、公差鏈到配置變更，用原創示意與紙上算例學習A350類客機的系統整合。","summaryEn":"Study A350-class airliner integration through original sketches and paper exercises on wing loads, composite directionality, tolerance chains and configuration change.","scope":"12道入門工程學習任務；引用A350公開背景，力學數值為明示教學假設。不是原廠鋪層表、裝配SOP、維修手冊、適航符合性證明或製造授權。","scopeEn":"Twelve introductory engineering tasks grounded in public A350 background, with explicitly hypothetical mechanics values. Not manufacturer layup schedules, assembly SOPs, maintenance instructions, airworthiness substantiation or manufacturing authorization.","contentStatus":"reviewable-educational-curriculum","sourceIds":["v6-a350-family","v6-a350-milestones","v6-faa-composites","v6-video-W0jlu0ghNIg"],"diagram":{"type":"aircraft","labels":["機身","機翼","接合介面","系統通道","驗證證據"],"labelsEn":["Fuselage","Wing","Joint interface","System routes","Verification evidence"],"original":true,"notToScale":true},"depth":4,"stages":[{"id":"c001-stage01","order":1,"title":"需求、載荷與基準","titleEn":"Requirements, loads and datums","description":"先定義系統邊界，再用質量、力矩及座標建立可追溯的整合問題。","descriptionEn":"Define boundaries, then use mass, moments and coordinates to establish traceable integration questions.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c001-v6-01","order":1,"sequence":1,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":[],"sourceIds":["v6-a350-family"],"title":"分配客機系統邊界","titleEn":"Allocate airliner system boundaries","objective":"把機體、動力、供電與控制的介面分開記錄。","objectiveEn":"Separate interfaces among airframe, propulsion, power and control.","instruction":"在紙上畫四個系統方塊，分別用實線、虛線表示載荷與資訊交換。以A350公開介紹辨識用途，再為每條箭頭寫下輸入、輸出與責任者；圖是你的原創示意。","instructionEn":"Draw four system blocks, using solid and dashed arrows for loads and information. Identify purposes from the public A350 overview, then label each interface with its input, output and owner. This is your own schematic.","observation":"觀察一條電源線與一項結構支承是否被錯當成同一種介面。","observationEn":"Check whether an electrical supply and a structural support have been treated as the same interface.","failure":"只列零件名稱而沒有交換量，會隱藏整合問題。","failureEn":"A parts list without exchanged quantities hides integration problems.","check":"至少列出一項機械、一項電力及一項資訊介面，各有可檢查的量。","checkEn":"Identify mechanical, electrical and information interfaces, each with a checkable quantity.","knowledge":[{"id":"c001-v6-01-k1","title":"功能與實體","titleEn":"Function and hardware","text":"一個功能可能跨越多個實體零件；方塊邊界是分析選擇。","textEn":"One function may span several physical parts; block boundaries are analytical choices."},{"id":"c001-v6-01-k2","title":"介面責任","titleEn":"Interface ownership","text":"輸出符合自己的規格，仍須與接收端假設相容。","textEn":"Meeting an output specification still requires compatibility with the receiving side."}],"quiz":{"question":"兩團隊零件各自合格，整合卻失敗，先查什麼？","questionEn":"Two teams pass their component checks but integration fails. What should be checked first?","options":["只確認各零件單獨合格即可接受整合","只核對總質量是否與原計畫相同","介面的交換量與假設是否一致"],"optionsEn":["Accept integration as soon as the individual parts pass","Check only whether total mass matches the original plan","Whether exchanged quantities and interface assumptions agree"],"answer":2,"explanation":"局部合格不自動證明跨系統相容。","explanationEn":"Local compliance does not automatically establish system compatibility."}},{"id":"c001-v6-02","order":2,"sequence":2,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-01"],"sourceIds":["v6-a350-family"],"title":"計算示意配重的重心","titleEn":"Calculate a schematic mass balance","objective":"以位置加權理解配置變更對重心的影響。","objectiveEn":"Use position-weighted mass to understand configuration changes.","instruction":"設兩個教學質量：2單位位於x=1，1單位位於x=4。算總質量與重心，再把後者移到x=7重算；所有數值均為無因次例題，不是飛機限制。","instructionEn":"Use teaching masses of 2 units at x=1 and 1 unit at x=4. Calculate total mass and center of mass, then move the latter to x=7 and recalculate. All values are dimensionless examples, not aircraft limits.","observation":"總質量不變，重心卻由2移到3。","observationEn":"Total mass stays constant while the center moves from 2 to 3.","failure":"直接平均兩個位置，等於錯把不同質量視為相等。","failureEn":"Averaging positions directly wrongly assigns equal weight to unequal masses.","check":"保留兩次力矩和，並用總質量除回重心。","checkEn":"Retain both moment sums and divide by total mass to recover the center.","knowledge":[{"id":"c001-v6-02-k1","title":"一階質量矩","titleEn":"First mass moment","text":"重心由Σmx／Σm求得，必須使用共同原點。","textEn":"The center is Σmx/Σm, using a common origin."},{"id":"c001-v6-02-k2","title":"配置管理","titleEn":"Configuration control","text":"搬動設備可能改變重心，即使沒有新增重量。","textEn":"Relocating equipment can change balance without adding mass."}],"quiz":{"question":"把同一設備往後移，哪項必然不變？","questionEn":"When the same item is moved aft, which quantity necessarily stays unchanged?","options":["重心位置","總質量","總質量矩"],"optionsEn":["Center-of-mass position","Total mass","Total mass moment"],"answer":1,"explanation":"位置改變影響力矩，不改變該設備質量。","explanationEn":"Changing position alters the moment, not the item’s mass."}},{"id":"c001-v6-03","order":3,"sequence":3,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-02"],"sourceIds":["v6-a350-family","v6-faa-composites"],"title":"追蹤機翼到機身的載荷路徑","titleEn":"Trace the wing-to-fuselage load path","objective":"區分分布載荷、接合處反力與局部應力。","objectiveEn":"Distinguish distributed load, joint reaction and local stress.","instruction":"畫一根固定端示意樑，把三支向上箭頭分布在翼展上。先令總力相同，再把箭頭外移；比较固定端彎矩。僅做紙上力學，不推算真機強度。","instructionEn":"Draw a fixed-end teaching beam with three upward arrows along its span. Keep total force unchanged, move the arrows outward and compare root bending moments. Use paper mechanics only, without inferring aircraft strength.","observation":"相同升力總和，作用點更遠時根部力矩增加。","observationEn":"The same total lift produces a larger root moment when applied farther out.","failure":"只比較總力會漏掉力臂，接頭也不能用外觀大小判定安全。","failureEn":"Comparing total force alone misses the lever arm; joint appearance cannot establish safety.","check":"每支箭頭標出到根部的距離，列出ΣFr。","checkEn":"Label each lever arm and calculate ΣFr.","knowledge":[{"id":"c001-v6-03-k1","title":"力臂","titleEn":"Lever arm","text":"力矩取決於力與其垂直作用距離。","textEn":"Moment depends on force and its perpendicular lever arm."},{"id":"c001-v6-03-k2","title":"局部與整體","titleEn":"Local and global response","text":"整體平衡提供反力，局部接頭仍需獨立驗證。","textEn":"Global equilibrium gives reactions; local joints still require separate substantiation."}],"quiz":{"question":"總升力不變、向翼尖移動，根部彎矩如何變化？","questionEn":"With total lift unchanged but moved toward the tip, how does root bending moment change?","options":["增大","必定降為零","因總力相同而不變"],"optionsEn":["It increases","It necessarily becomes zero","It is unchanged because total force is unchanged"],"answer":0,"explanation":"外移增加力臂，因此增加根部力矩。","explanationEn":"Moving the load outward increases its lever arm and root moment."}},{"id":"c001-v6-04","order":4,"sequence":4,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-03"],"sourceIds":["v6-faa-composites"],"title":"核對裝配基準與公差鏈","titleEn":"Check assembly datums and tolerance chains","objective":"讓兩個分段使用一致的座標與驗收基準。","objectiveEn":"Give two sections consistent coordinates and acceptance datums.","instruction":"在兩張原創機身分段圖標出共同原點、軸向和接合平面。假設兩段偏差各為±0.4示意單位，求最壞相對錯位，再與假設允收±0.6比較。","instructionEn":"Mark a shared origin, axes and mating plane on two original fuselage-section sketches. Assume each has an error of ±0.4 teaching units. Find the worst relative mismatch and compare with an assumed ±0.6 allowance.","observation":"單段各自合格，反向偏差仍可能造成0.8錯位。","observationEn":"Individually acceptable sections can still mismatch by 0.8 when errors oppose.","failure":"混用機身座標與局部治具座標，會產生看似固定的系統偏差。","failureEn":"Mixing body and fixture frames can create an apparently fixed systematic offset.","check":"指出最壞組合，且圖上所有尺寸可追溯到相同基準。","checkEn":"Identify the worst combination and trace every dimension to the common datum.","knowledge":[{"id":"c001-v6-04-k1","title":"基準","titleEn":"Datum","text":"尺寸的意義依賴其參考平面與方向。","textEn":"A dimension depends on its reference plane and direction."},{"id":"c001-v6-04-k2","title":"公差累積","titleEn":"Tolerance accumulation","text":"最壞相對誤差需考慮兩零件朝相反方向偏移。","textEn":"Worst relative error includes opposite deviations of the two parts."}],"quiz":{"question":"兩段各±0.4，最壞相對錯位是多少？","questionEn":"For two sections each at ±0.4, what is the worst relative mismatch?","options":["0.4","0.16","0.8"],"optionsEn":["0.4","0.16","0.8"],"answer":2,"explanation":"一段+0.4、另一段−0.4，差為0.8。","explanationEn":"One at +0.4 and the other at −0.4 differ by 0.8."}}]},{"id":"c001-stage02","order":2,"title":"材料回應與損傷證據","titleEn":"Material response and damage evidence","description":"比较方向性、熱相容、檢測範圍與循環載荷；不替代任何實機材料試驗。","descriptionEn":"Compare directionality, thermal compatibility, inspection scope and cyclic loading without replacing aircraft material tests.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c001-v6-05","order":1,"sequence":5,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-04"],"sourceIds":["v6-faa-composites"],"title":"辨識複材方向性","titleEn":"Identify composite directionality","objective":"把纖維方向與載荷方向連在一起。","objectiveEn":"Relate fiber direction to loading direction.","instruction":"畫三張試片示意：纖維沿0°、90°及混合方向。對同一軸向拉力標出纖維與基材可能扮演的角色；只提出待測假設，不自填材料強度。","instructionEn":"Sketch coupons with fibers at 0°, 90° and mixed orientations. Under the same axial load, identify possible fiber and matrix roles. Record hypotheses requiring tests instead of inventing strength values.","observation":"旋轉試片方向會改變材料回應，即使外形與厚度相同。","observationEn":"Rotating the material direction can alter response despite identical shape and thickness.","failure":"把複材當作各方向相同的金屬，會掩蓋方向性與層間問題。","failureEn":"Treating a laminate as direction-independent metal hides anisotropy and interlaminar issues.","check":"每張試片都有載荷箭頭、纖維方向及一項待驗證假設。","checkEn":"Each coupon shows a load arrow, fiber orientation and a testable hypothesis.","knowledge":[{"id":"c001-v6-05-k1","title":"異向性","titleEn":"Anisotropy","text":"複材性質可能隨方向改變，不能只用單一強度數字描述。","textEn":"Composite properties can vary by direction and cannot be described by one strength value alone."},{"id":"c001-v6-05-k2","title":"基材功能","titleEn":"Matrix role","text":"基材保持纖維配置並傳遞載荷，不能視為無功能的填充物。","textEn":"The matrix maintains fiber arrangement and transfers load; it is not an inert filler."}],"quiz":{"question":"兩試片外形一樣卻反應不同，哪項應優先核對？","questionEn":"Two equal-shaped coupons respond differently. Which factor should be checked first?","options":["只比較外形與厚度是否相同","纖維方向與鋪層資訊","只核對總質量，不看鋪層"],"optionsEn":["Compare only external shape and thickness","Fiber orientation and laminate information","Check only mass without examining the layup"],"answer":1,"explanation":"方向與鋪層直接影響複材力學回應。","explanationEn":"Orientation and layup directly affect composite mechanical response."}},{"id":"c001-v6-06","order":2,"sequence":6,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-05"],"sourceIds":["v6-faa-composites"],"title":"比較異材接合的熱伸長","titleEn":"Compare thermal expansion at a mixed-material joint","objective":"理解相連材料自由伸長不同的後果。","objectiveEn":"Understand consequences of unequal free thermal expansion.","instruction":"假設兩條等長教學材料的熱膨脹係數為2與10個相同單位，在相同升溫下比較自由伸長比。再畫出端部被共同約束的情境，列出需要分析的接頭反力。","instructionEn":"Assume equal-length teaching strips with expansion coefficients of 2 and 10 in the same units. Compare free expansion under equal heating, then sketch a shared end restraint and identify joint reactions needing analysis.","observation":"較大係數的自由伸長為另一條的5倍；接合後不能各自自由伸長。","observationEn":"The higher-coefficient strip expands five times as much freely; joined strips cannot both follow their free expansion.","failure":"把自由熱伸長直接當作受約束後的實際位移，忽略了相容条件。","failureEn":"Using free expansion as constrained displacement ignores compatibility.","check":"分別列出自由伸長與約束後需解的未知量，不猜接頭應力值。","checkEn":"Separate free expansion from unknown constrained quantities without guessing joint stress.","knowledge":[{"id":"c001-v6-06-k1","title":"熱應變","titleEn":"Thermal strain","text":"自由熱應變由膨脹係數乘溫度變化得到。","textEn":"Free thermal strain is expansion coefficient times temperature change."},{"id":"c001-v6-06-k2","title":"相容條件","titleEn":"Compatibility","text":"被接在一起的部位須同時滿足幾何相容與力平衡。","textEn":"Connected parts must satisfy both geometric compatibility and force equilibrium."}],"quiz":{"question":"自由伸長不同的材料被接合後，還需加入什麼？","questionEn":"What must be added when joining materials with different free expansions?","options":["約束與相容條件","把較小伸長直接刪掉","假設接頭永遠沒有反力"],"optionsEn":["Restraints and compatibility conditions","Discard the smaller expansion","Assume the joint never develops a reaction"],"answer":0,"explanation":"接頭限制相對移動，可能因此產生內力。","explanationEn":"The joint limits relative movement and can generate internal forces."}},{"id":"c001-v6-07","order":3,"sequence":7,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-06"],"sourceIds":["v6-faa-composites"],"title":"建立複材檢查的證據地圖","titleEn":"Map composite inspection evidence","objective":"區分表面觀察與內部損傷的證據。","objectiveEn":"Distinguish surface observation from internal-damage evidence.","instruction":"畫一片有表面撞痕與假設層間缺陷的示意板。把目視、適用的非破壞檢測與後續工程評估放在不同欄位；為每種方法註明它能回答與不能回答的問題。","instructionEn":"Draw a panel with a surface impact mark and a hypothetical internal defect. Separate visual inspection, applicable nondestructive inspection and engineering assessment into columns, stating what each can and cannot answer.","observation":"外表平整不能排除內部異常，檢測訊號也不自動等於可放行。","observationEn":"A smooth surface cannot rule out internal anomalies, and a signal alone does not authorize release.","failure":"用照片替代經核准的檢測與判讀，會把未知狀態誤標合格。","failureEn":"Substituting a photo for approved inspection and interpretation mislabels uncertainty as acceptance.","check":"至少一項未知量保留為待確認，並列出需要的合格判讀證據。","checkEn":"Retain at least one unresolved question and identify the qualified interpretation needed.","knowledge":[{"id":"c001-v6-07-k1","title":"損傷容限","titleEn":"Damage tolerance","text":"發現、評估和處置損傷是不同工作。","textEn":"Detecting, assessing and dispositioning damage are separate tasks."},{"id":"c001-v6-07-k2","title":"檢測範圍","titleEn":"Inspection coverage","text":"每種方法有適用材料、幾何與缺陷範圍。","textEn":"Every method has applicable materials, geometries and defect classes."}],"quiz":{"question":"沒有看見裂痕，能直接得出哪個結論？","questionEn":"No crack is visible. Which conclusion is justified?","options":["所有內部層間皆完整","已符合真機放行要求","目前目視範圍沒有可見裂痕"],"optionsEn":["All internal interfaces are intact","The aircraft release requirements are satisfied","No visible crack was found within the visual inspection scope"],"answer":2,"explanation":"證據只能支援其觀察範圍內的結論。","explanationEn":"Evidence supports conclusions only within its observation scope."}},{"id":"c001-v6-08","order":4,"sequence":8,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-07"],"sourceIds":["v6-faa-composites"],"title":"區分靜態強度與循環疲勞","titleEn":"Separate static strength from cyclic fatigue","objective":"用載荷歷程而非一次峰值描述耐久問題。","objectiveEn":"Describe durability through load history rather than one peak.","instruction":"自畫兩條無因次載荷曲線：一次峰值與多次較低振幅循環。標記循環數、平均值和振幅，列出需要何種試驗資料才能比較壽命；不自行推算服役年限。","instructionEn":"Draw dimensionless load histories: one peak and repeated lower-amplitude cycles. Mark cycle count, mean and amplitude, then identify test data needed to compare life. Do not infer service years.","observation":"低於一次試驗峰值的循環載荷，仍可能累積損傷。","observationEn":"Repeated loading below a single-test peak can still accumulate damage.","failure":"一次靜載通過就宣稱無限壽命，混淆了不同驗證目的。","failureEn":"Claiming unlimited life after one static pass confuses different verification purposes.","check":"報告分開寫靜態判定、循環資料與尚未回答的壽命問題。","checkEn":"Report static assessment, cyclic data and unanswered life questions separately.","knowledge":[{"id":"c001-v6-08-k1","title":"载荷歷程","titleEn":"Load history","text":"疲勞問題包含次數、振幅、平均值與順序。","textEn":"Fatigue problems include count, amplitude, mean and sequence."},{"id":"c001-v6-08-k2","title":"驗證範圍","titleEn":"Verification scope","text":"一種試驗合格不自動覆蓋所有失效機制。","textEn":"Passing one test does not cover every failure mechanism."}],"quiz":{"question":"靜載測試通過後，仍不能直接宣稱什麼？","questionEn":"After passing a static test, what still cannot be claimed directly?","options":["仍需要辨識使用載荷歷程","已證明所有循環疲勞壽命","該靜載情境已取得一項證據"],"optionsEn":["The service-load history still needs identification","Every cyclic-fatigue life requirement is proven","Evidence exists for that static-load case"],"answer":1,"explanation":"靜態與疲勞的驗證對象不同。","explanationEn":"Static and fatigue verification address different behavior."}}]},{"id":"c001-stage03","order":3,"title":"系統整合與配置交付","titleEn":"System integration and configuration handover","description":"把冗餘、空間、變更及證據成熟度納入同一份工程紀錄。","descriptionEn":"Bring redundancy, space, change and evidence maturity into one engineering record.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c001-v6-09","order":1,"sequence":9,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-08"],"sourceIds":["v6-a350-family"],"title":"檢查冗餘電源的共同依賴","titleEn":"Check shared dependencies in redundant power","objective":"避免把兩條線路誤認成兩套獨立供電。","objectiveEn":"Avoid confusing two wires with two independent supplies.","instruction":"畫两路教學電源供應同一感測器，先讓它們共用一個上游開關，再另畫分開的上游路徑。用紙上斷點逐一追蹤失效影響，不模擬真機電路。","instructionEn":"Draw two teaching supplies feeding one sensor, first sharing an upstream switch and then using separate upstream paths. Trace failures with paper break points, without simulating an aircraft circuit.","observation":"共用開關失效可同時切斷兩條下游線路。","observationEn":"A shared switch failure can interrupt both downstream paths.","failure":"只數備份元件，未檢查共同依賴，會高估可用性。","failureEn":"Counting backup components without shared-dependency analysis overstates availability.","check":"標出至少一個共同失效點及其影響，將未知獨立性列為待驗證。","checkEn":"Mark a common failure point and its effect, retaining unproven independence as an open item.","knowledge":[{"id":"c001-v6-09-k1","title":"共同原因","titleEn":"Common cause","text":"相同來源或環境可能同時影響看似分開的設備。","textEn":"A shared source or environment can affect apparently separate equipment."},{"id":"c001-v6-09-k2","title":"失效傳播","titleEn":"Failure propagation","text":"系統邊界上的依賴決定故障如何擴散。","textEn":"Dependencies across boundaries determine how faults propagate."}],"quiz":{"question":"兩路電源共用上游開關，該開關失效代表什麼？","questionEn":"Two supplies share an upstream switch. What does its failure imply?","options":["兩路可能同時失去供電","必定只有一路受影響","下游有兩條線就不受影響"],"optionsEn":["Both paths may lose power together","Only one path can be affected","Two downstream wires prevent any effect"],"answer":0,"explanation":"路徑數量不能取代獨立性分析。","explanationEn":"Path count is not a substitute for independence analysis."}},{"id":"c001-v6-10","order":2,"sequence":10,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-09"],"sourceIds":["v6-a350-family","v6-faa-composites"],"title":"審查管線與維修可達性","titleEn":"Review routing and maintenance access","objective":"在原創配置圖上辨識跨系統的空間衝突。","objectiveEn":"Identify cross-system spatial conflicts on an original layout.","instruction":"畫一段機身設備艙示意，放入管線、線束、支承與可拆面板。先標運動及熱源區，再安排檢查視線和拆卸路徑；尺寸只用自訂教學單位。","instructionEn":"Sketch a fuselage equipment bay with pipes, wiring, supports and a removable panel. Mark moving and hot zones, then inspection sightlines and removal paths. Use invented teaching units only.","observation":"在安裝時放得進去，不代表日後能安全檢查或取出。","observationEn":"Fitting during installation does not ensure later inspection or removal access.","failure":"只看靜止的正視圖，可能漏掉運動包络或拆卸空間。","failureEn":"A static front view may hide motion envelopes or removal clearances.","check":"為一項元件畫出完整移出路徑，並列出至少一項介面衝突。","checkEn":"Draw a complete removal path for one item and identify an interface conflict.","knowledge":[{"id":"c001-v6-10-k1","title":"維護設計","titleEn":"Design for maintenance","text":"可達性是生命周期需求，不是完工後才處理的附加項。","textEn":"Access is a lifecycle requirement rather than an afterthought."},{"id":"c001-v6-10-k2","title":"空間包络","titleEn":"Spatial envelope","text":"位置、運動、工具與拆卸路徑佔用不同空間。","textEn":"Installed position, motion, tools and removal paths occupy different spaces."}],"quiz":{"question":"元件安裝後被固定管線擋住，主要漏了什麼？","questionEn":"A fixed pipe blocks an installed component’s removal. What was omitted?","options":["只確認最初裝配時元件放得進去","只比較檢修口面積而不檢查移出路徑","維修拆卸的空間介面"],"optionsEn":["Confirm only that the component fitted during initial assembly","Compare access-panel area without checking the removal path","The maintenance-removal spatial interface"],"answer":2,"explanation":"維修需要考慮整條拆卸路徑。","explanationEn":"Maintenance requires considering the entire removal path."}},{"id":"c001-v6-11","order":3,"sequence":11,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-10"],"sourceIds":["v6-faa-composites"],"title":"追蹤設計變更的影響鏈","titleEn":"Trace a design-change impact chain","objective":"讓一項材料變更連回所有受影響的證據。","objectiveEn":"Connect a material change to every affected evidence item.","instruction":"設想教學支架由材料甲改為乙。建立變更卡，逐欄檢查質量、熱膨脹、接合、檢測方式及圖面版本；未知欄寫待確認，不自行批准替代。","instructionEn":"Imagine changing a teaching bracket from material A to B. Create a change card covering mass, thermal expansion, joining, inspection and drawing revision. Mark unknowns for review rather than approving substitution.","observation":"外形相同的支架仍可能改變負載與檢驗需求。","observationEn":"An equal-shaped bracket may still change loads and inspection needs.","failure":"只更新採購名稱而保留舊驗證結論，會切斷配置追溯。","failureEn":"Updating only the purchase name while keeping old verification breaks configuration traceability.","check":"變更卡至少連到兩項需重新審查的既有證據。","checkEn":"Link the change card to at least two existing evidence items requiring review.","knowledge":[{"id":"c001-v6-11-k1","title":"配置基線","titleEn":"Configuration baseline","text":"驗證結果只對特定版本與假設成立。","textEn":"Verification results apply to a particular revision and assumptions."},{"id":"c001-v6-11-k2","title":"變更影響","titleEn":"Change impact","text":"一項局部替換可能跨越結構、熱與維護介面。","textEn":"A local substitution may cross structural, thermal and maintenance interfaces."}],"quiz":{"question":"材料已更換、外形不變，舊驗證可以如何處理？","questionEn":"Material changes but shape does not. How should previous verification be treated?","options":["外形相同就自動沿用所有舊證據","先審查適用性與影響，再決定需重做部分","僅比較新舊材料密度，不審查其他介面"],"optionsEn":["Automatically reuse every old result because shape is unchanged","Review applicability and impact before selecting re-verification","Compare only density without reviewing other interfaces"],"answer":1,"explanation":"外形一致不足以證明材料變更沒有影響。","explanationEn":"Equal geometry does not establish that a material change has no effect."}},{"id":"c001-v6-12","order":4,"sequence":12,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c001-v6-11"],"sourceIds":["v6-a350-family","v6-a350-milestones","v6-faa-composites"],"title":"組成分層驗證證據包","titleEn":"Assemble a layered verification dossier","objective":"把分析、試片、分系統與整合的證據分層。","objectiveEn":"Separate analysis, coupon, subsystem and integration evidence.","instruction":"將前十一道工序的筆記排成矩陣，每列是一項需求，每欄是一種證據。明確標示教學推論、引用事實與尚缺測試；選一項接合需求追蹤到底。","instructionEn":"Arrange the previous eleven task notes in a matrix with requirements as rows and evidence types as columns. Mark teaching deductions, cited facts and missing tests. Trace one joint requirement through the layers.","observation":"完整欄位不代表實際取得證據，空缺應維持可見。","observationEn":"A filled form does not mean evidence was obtained; gaps must remain visible.","failure":"用漂亮模型截圖代替結構試驗或審查紀錄，會高估完成度。","failureEn":"Replacing structural tests or review records with attractive model screenshots overstates completion.","check":"交付一條可追溯證據鏈，且沒有把本課程當作真機製造放行。","checkEn":"Deliver a traceable evidence chain without treating the course as an aircraft manufacturing release.","knowledge":[{"id":"c001-v6-12-k1","title":"驗證階層","titleEn":"Verification hierarchy","text":"局部材料表現與整機整合是不同尺度的問題。","textEn":"Local material behavior and aircraft integration are different scales of problem."},{"id":"c001-v6-12-k2","title":"證據成熟度","titleEn":"Evidence maturity","text":"假設、計畫與已完成量測應有不同狀態。","textEn":"Assumptions, plans and completed measurements need distinct status labels."}],"quiz":{"question":"哪項最適合標為「待取得證據」？","questionEn":"Which item should be marked as evidence still to obtain?","options":["已規劃但尚未執行的試驗","已引用並核對的公開首飛日期","已算出的教學重心例題"],"optionsEn":["A planned but unperformed test","A checked and cited public first-flight date","A completed classroom center-of-mass calculation"],"answer":0,"explanation":"試驗計畫不等於試驗結果。","explanationEn":"A test plan is not a test result."}}]}],"stepCount":12,"estimatedMinutes":216,"languageCoverage":["zh-TW","en"],"status":"guided","kind":"course","curriculumVersion":6}};
